# GENERATED by tools/hanjuku_speedrun_fork.py from bbe3144d334054674da32c03b229e7a3c32938b5. Do not edit until the freeze (see docs/features/hanjuku-speedrun-corner.md).
"""The title screen must never overwrite a run that has progress.

g1190 2026-11-16: a saved state booted to the title, Start confirmed
「はじめから」 and the chapter-9 progress was lost.  The bounded つづき
retries (down/wait/A) are the fix; these tests pin the two remaining
holes — the retry counter outliving its title episode, and the fallback to
Start for a run that already identified a chapter.
"""
from pathlib import Path
import sys

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'src'))

from docich.hanjuku_speedrun.hanjuku.os_layer.phase import classify
from docich.hanjuku_speedrun.hanjuku.orchestrator import TITLE_CONTINUE_TRIES, decide
from docich.hanjuku_speedrun.hanjuku_pixels import Frame, read_png

FIXTURE = Path(__file__).resolve().parent.parent / 'fixtures/hanjuku/g1190-title-after-chapter.png'
CONTINUE = [{'type': 'pad', 'buttons': ['down'], 'hold_ms': 100},
            {'type': 'wait', 'ms': 200},
            {'type': 'pad', 'buttons': ['a'], 'hold_ms': 100}]


def title_frame():
    frame = read_png(FIXTURE).resized()
    assert classify(frame) == 'title'
    return frame


def playable_frame():
    """A frame the bot recognises as the game world (title episode is over)."""
    frame = read_png(Path(__file__).resolve().parent.parent
                     / 'fixtures/hanjuku/g1190-ch9-desert-field.png').resized()
    assert classify(frame) == 'field'
    return frame


def title_fade_frame():
    """The title's own fade: dark with a bright corner, not a menu."""
    width, height = 256, 224
    rgb = bytearray(width * height * 3)
    for y in range(height):
        for x in range(width):
            value = 120 if (x < 60 and y < 60) else 5
            offset = (y * width + x) * 3
            rgb[offset:offset + 3] = bytes((value, value, value))
    frame = Frame(width, height, bytes(rgb))
    assert classify(frame) == 'title_or_intro'
    return frame


def step_bot(frame, state):
    actions, updated = decide(frame, state)
    return actions, updated


def test_title_continue_retries_stop_at_the_bound():
    state = {'policy': {'chapter': 9, 'tick': 1}, 'step': 1}
    for _ in range(TITLE_CONTINUE_TRIES):
        actions, state = step_bot(title_frame(), state)
        assert actions == CONTINUE
        assert 'start' not in [b for action in actions if action['type'] == 'pad'
                               for b in action['buttons']]


def test_a_run_with_a_chapter_never_falls_through_to_start():
    state = {'policy': {'chapter': 9, 'tick': 1}, 'step': 1}
    for _ in range(TITLE_CONTINUE_TRIES):
        _, state = step_bot(title_frame(), state)
    actions, state = step_bot(title_frame(), state)
    assert actions == []
    records = state.get('_records') or []
    assert records[-1]['decision'] == 'title_continue_exhausted'
    assert records[-1]['observed_metric']['chapter'] == 9
    # Later observations stay held instead of pressing Start.
    actions, state = step_bot(title_frame(), state)
    assert actions == []
    assert sum(1 for r in state.get('_records') or []
               if r.get('decision') == 'title_continue_exhausted') <= 1


def test_a_chapterless_cartridge_still_starts():
    state = {'policy': {'tick': 1}, 'step': 1}
    for _ in range(TITLE_CONTINUE_TRIES):
        _, state = step_bot(title_frame(), state)
    actions, _ = step_bot(title_frame(), state)
    assert actions == [{'type': 'pad', 'buttons': ['start'], 'hold_ms': 100}]


def test_a_title_fade_stays_inside_the_title_episode():
    state = {'policy': {'chapter': 9, 'tick': 1}, 'step': 1}
    actions, state = step_bot(title_frame(), state)
    assert actions == CONTINUE
    actions, state = step_bot(title_fade_frame(), state)
    assert actions == CONTINUE
    for _ in range(TITLE_CONTINUE_TRIES):
        actions, state = step_bot(title_frame(), state)
    assert actions == []
    actions, state = step_bot(title_fade_frame(), state)
    assert actions == []  # never the generic confirm that starts a new game


def test_leaving_the_title_resets_the_continue_budget():
    state = {'policy': {'chapter': 9, 'tick': 1}, 'step': 1}
    for _ in range(TITLE_CONTINUE_TRIES):
        _, state = step_bot(title_frame(), state)
    assert (state.get('title_tries') or {}).get('n') == TITLE_CONTINUE_TRIES
    _, state = step_bot(playable_frame(), state)
    assert 'title_tries' not in state
    # A second title episode tries つづき again instead of pressing Start.
    actions, state = step_bot(title_frame(), state)
    assert actions == CONTINUE
